import { test, expect } from '@playwright/test';

test.describe('Background Sync Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should display toast notification on background sync completion', async ({ page }) => {
    // Trigger the background sync
    await page.click(getByRole('button', { name: /start sync/i }));

    // Wait for the background sync to complete
    await page.waitForResponse(response => response.url().includes('/sync-endpoint') && response.status() === 200);

    // Assert that the toast notification is visible
    const toast = page.getByRole('alert', { name: /sync completed successfully/i });
    await expect(toast).toBeVisible();
  });

  test('should not display toast notification if sync fails', async ({ page }) => {
    // Trigger the background sync with a failure scenario
    await page.click(getByRole('button', { name: /start sync with error/i }));

    // Wait for the background sync to complete
    await page.waitForResponse(response => response.url().includes('/sync-endpoint') && response.status() === 500);

    // Assert that the toast notification is not visible
    const toast = page.getByRole('alert', { name: /sync completed successfully/i });
    await expect(toast).not.toBeVisible();
  });
});
